function resolveKeyForVersion(version) {
	const envKey = getEnv(`ENCRYPTION_KEY_V${version}`)?.trim();
	if (!envKey) {
		return null;
	}
	if (/^[0-9a-fA-F]{64}$/.test(envKey)) {
		return Buffer.from(envKey, "hex");
	}
	if (envKey.length === KEY_BYTES) {
		return Buffer.from(envKey, "utf8");
	}
	throw new Error(`FieldCrypto: ENCRYPTION_KEY_V${version} must be 32 utf8 chars or 64 hex chars`);
}

